#!/data/data/com.termux/files/usr/bin/bash
# apply_all23.sh - العربية 1AM: حذف أرقام الصفحات من نصوص المقاطع + «الفكرة العامة» و«الأفكار الأساسية» لنصوص المقطع 2
# يعدّل سطر بيانات TA في www/maps.html فقط (استبدال نصوص محددة). لا يمسّ مفتاح الترخيص.
cd ~/zad-1am/www 2>/dev/null || cd "$(dirname "$0")/www" || { echo "لم أجد مجلد www"; exit 1; }
[ -f maps.html.bak_am1ar ] || cp maps.html maps.html.bak_am1ar
if grep -q 'الأفكار الأساسية (1): «حب الوطن من الإيمان»' maps.html; then
  echo "التعديل مطبَّق من قبل. لا شيء لفعله."; exit 0
fi
sed -i '/^const TASEC=/s|"أمّ السعد (حصتان) ص89"|"أمّ السعد (حصتان)"|' maps.html
sed -i '/^const TASEC=/s|"ابنتي ص12 وعلامات الوقف"|"ابنتي وعلامات الوقف"|' maps.html
sed -i '/^const TASEC=/s|"أبي ص14: الشعر والنثر"|"أبي: الشعر والنثر"|' maps.html
sed -i '/^const TASEC=/s|"سطر أحمر من الأمس ص97"|"سطر أحمر من الأمس"|' maps.html
sed -i '/^const TASEC=/s|"حب الوطن من الإيمان ص32"|{"s":"حب الوطن من الإيمان","i":["الفكرة العامة: حب الوطن من الإيمان: فعلى المؤمن أن يحب وطنه ويخلص له ويعمل لنفعه، دون أن يبغض الأوطان الأخرى أو يضرها.","الأفكار الأساسية (1): «حب الوطن من الإيمان» كلمة تجري على ألسنة المسلمين، ومعناها صحيح ثابت.","الأفكار الأساسية (2): الوطن أصل تكوين الإنسان: منه غذاء الوالدين ثم غذاؤه، بترابه ومائه وهوائه ونباته وحيوانه، وفيه مسرح طفولته وشبابه.","الأفكار الأساسية (3): الإسلام لم يأتِ بمحبة الوطن إلا بما تقتضيه الفطرة ويقبله العقل ويعترف به حكماء الأمم، ومنهم العالم «هيريو» الذي نصح الأمة العربية بحب وطنها.","الأفكار الأساسية (4): المحبة الصادقة تظهر في الإخلاص في العمل: أن تجعل أعمالك عائدة بالخير على وطنك وتخدمه بما زرعت له من محبة في قلوب الناس.","الأفكار الأساسية (5): أحبّ وطنك ولا تبغض الأوطان الأخرى ولا تضرّ بها، بل كن مصدر محبة شاملة ونفع عام."]}|' maps.html
sed -i '/^const TASEC=/s|"فداء الجزائر ص40"|{"s":"فداء الجزائر","i":["الفكرة العامة: عملية فدائية بطولية في حي القصبة قام بها مخلوف وزهور وسط جنود المظليين، دفاعا عن الجزائر وتضحية في سبيلها.","الأفكار الأساسية (1): مرور الراوية أمام المظليين في مدخل حي القصبة، وأمرهم مخلوفا أن يرفع يديه ويستدير إلى الجدار ثم تفتيشه.","الأفكار الأساسية (2): انتظارها «الكلمة الرهيبة» التي تأمرها بالوقوف، ثم مرورها بسلام ولحاقها بمخلوف في منعطف الشارع.","الأفكار الأساسية (3): اقتراب مخلوف وزهور من مركز الشرطة، وطلبه قنبلة منها، ثم انفجار هائل هزّ أركان المدينة.","الأفكار الأساسية (4): ظهور دورية عسكرية مقبلة، فاندفع مخلوف بشجاعة ورمى القنبلة الثانية.","الأفكار الأساسية (5): ختام النص: طلقات مدفع رشاش وصوت يصرخ بافتخار: «تحيا الجزائر»."]}|' maps.html
sed -i '/^const TASEC=/s|"للحرية الحمراء ص28: الصدر والعجز"|{"s":"للحرية الحمراء: الصدر والعجز","i":["الفكرة العامة: الحرية لا تُنال إلا بالتضحية بالدم والنفس، والعرب يجمعهم همّ واحد ولسان واحد وإن اختلفت بلدانهم.","الأفكار الأساسية (1): البيتان 1-3: ينصح الشاعر بني سورية بطرح الأماني والأحلام، ويرى أن تغيير ألقاب الإمارة من خدع السياسة، ويعلل تدخله بأن العرب كلهم في الهمّ شرق.","الأفكار الأساسية (2): البيت 4: يجمع العرب البيان والنطق (اللغة) وإن اختلفت بلادهم.","الأفكار الأساسية (3): البيتان 5-6: من أراد نعيم الحياة فليتحمل الشقاء، ومن أراد الموت فليقف بين الحياة والموت، وللأوطان في دم كل حر دين مستحق.","الأفكار الأساسية (4): البيتان 7-8: لا تُبنى الممالك ولا تُنال الحقوق إلا بالتضحيات.","الأفكار الأساسية (5): البيتان 9-10: في القتلى حياة للأجيال وفي الأسرى فداء وعتق، وللحرية الحمراء باب بكل يد مضرجة يدق."]}|' maps.html
sed -i '/^const TASEC=/s|"ثق يا أيها الوطن: البيت الشعري"|{"s":"ثق يا أيها الوطن: البيت الشعري","i":["الفكرة العامة: شاعر يودّع وطنه مضطرا للرحيل بجسده وقلبه باق فيه، ويعلن استعداده وشعبه للدفاع عنه، ويطمئن الوطن بأن له ضمائر لا تباع.","الأفكار الأساسية (1): البيتان 1-2: أزف الرحيل فيودع الشاعر منبت العظماء، وسيرحل وقلبه عند وطنه يحييه دائما.","الأفكار الأساسية (2): البيتان 3-4: للسعي والعمل نفع عظيم لشعب أضعفه الضياع، وما نهضت بلاد الضعف إلا بذلك.","الأفكار الأساسية (3): البيتان 5-6: إذا كاد الأعداء للوطن بذل الشعب ما لديه واتخذ النفوس معاقل وقلاعا.","الأفكار الأساسية (4): الأبيات 7-9: يعلم الشاعر الأضداد أن الشعب يريد حقا مشاعا، وهو أهل للسلم وإن حورب فله قوة وسلاح فاتك من الحق العزيز.","الأفكار الأساسية (5): البيت 10: ختام يخاطب فيه الوطن المفدّى: ثق بأن لك ضمائر لن تباع."]}|' maps.html
sed -i '/^const TASEC=/s|"نوفمبر: التشبيه"|{"s":"نوفمبر: التشبيه","i":["الفكرة العامة: تمجيد ثورة نوفمبر الجزائرية والافتخار برجالها وبطولاتهم وصمودهم.","الأفكار الأساسية (1): البيتان 1-2: الجزائر منبع الثائرين وثورة الماجدين وموطن الظافرين.","الأفكار الأساسية (2): البيتان 3-4: فيها شعلة الثورات في رياض الحماة من أباة وكماة وسراة.","الأفكار الأساسية (3): البيتان 5-6: طردنا المستعمر وكنا كأسود الشرى، والثورة شملت المدن والقرى والرجال والحرائر.","الأفكار الأساسية (4): البيتان 7-8: يدعو الشاعر إلى ترديد الفخر بأنهم الأولى وقفوا لنيل العلى والشرف.","الأفكار الأساسية (5): البيتان 9-10: جبل الأوراس يشهد أنهم صمدوا كراما بوسائل بسيطة، ومنه أتت البشائر."]}|' maps.html
sed -i '/^const TASEC=/s|"البشير الإبراهيمي ص105"|"البشير الإبراهيمي"|' maps.html
sed -i '/^const TASEC=/s|"سر عظمة الرسول ﷺ ص52"|"سر عظمة الرسول ﷺ"|' maps.html
sed -i '/^const TASEC=/s|"الرازي طبيبا عظيما ص60"|"الرازي طبيبا عظيما"|' maps.html
sed -i '/^const TASEC=/s|"ماسينيسا ص66: التعبير المجازي"|"ماسينيسا: التعبير المجازي"|' maps.html
sed -i '/^const TASEC=/s|"جميلة بوحيرد ص54: الأسلوب الإنشائي"|"جميلة بوحيرد: الأسلوب الإنشائي"|' maps.html
sed -i '/^const TASEC=/s|"عمر ورسول كسرى ص58: الجناس"|"عمر ورسول كسرى: الجناس"|' maps.html
sed -i '/^const TASEC=/s|"روان والقلم ص113"|"روان والقلم"|' maps.html
sed -i '/^const TASEC=/s|"آيات من سورة الحجرات ص72"|"آيات من سورة الحجرات"|' maps.html
sed -i '/^const TASEC=/s|"الوقيعة ص76"|"الوقيعة"|' maps.html
sed -i '/^const TASEC=/s|"إنّ لكم معالم ص80: السجع"|"إنّ لكم معالم: السجع"|' maps.html
sed -i '/^const TASEC=/s|"ازدياد حرارة الأرض ص127"|"ازدياد حرارة الأرض"|' maps.html
sed -i '/^const TASEC=/s|"الكتاب الإلكتروني ص92"|"الكتاب الإلكتروني"|' maps.html
sed -i '/^const TASEC=/s|"الفيسبوك نعمة أم نقمة ص96"|"الفيسبوك نعمة أم نقمة"|' maps.html
sed -i '/^const TASEC=/s|"المستكشفات العلمية ص106: الأسلوب العلمي"|"المستكشفات العلمية: الأسلوب العلمي"|' maps.html
sed -i '/^const TASEC=/s|"اجتلاء العيد ص131"|"اجتلاء العيد"|' maps.html
sed -i '/^const TASEC=/s|"الأعياد ص112"|"الأعياد"|' maps.html
sed -i '/^const TASEC=/s|"هدية العيد ص116"|"هدية العيد"|' maps.html
sed -i '/^const TASEC=/s|"عيد القرية ص124"|"عيد القرية"|' maps.html
sed -i '/^const TASEC=/s|"الطبيعة والإنسان ص137"|"الطبيعة والإنسان"|' maps.html
sed -i '/^const TASEC=/s|"في الغابة ص132"|"في الغابة"|' maps.html
sed -i '/^const TASEC=/s|"بين الريف والمدينة ص136"|"بين الريف والمدينة"|' maps.html
sed -i '/^const TASEC=/s|"مرض زينب ص145"|"مرض زينب"|' maps.html
sed -i '/^const TASEC=/s|"أهمية التربية الرياضية ص152"|"أهمية التربية الرياضية"|' maps.html
sed -i '/^const TASEC=/s|"ركوب الخيل ص154"|"ركوب الخيل"|' maps.html
sed -i '/^const TASEC=/s|"كرة القدم ص158"|"كرة القدم"|' maps.html
echo "---- تحقق ----"
grep -c 'الأفكار الأساسية (1): «حب الوطن من الإيمان»' maps.html
echo "تم. نسخة احتياطية: maps.html.bak_am1ar"
